//! Markdown: a typed facade of a JavaScript library (`zebkit::js::Library`).
//! Generated by tools/js-bundle.mjs --wrapper rust from its exports.json; do not edit.

#![allow(dead_code)]

use zebkit::js::{Code, Library, LibraryError};
use zebkit::json::Value;

pub struct Markdown {
    pub library: Library,
}

fn unexpected(function: &str, what: &str) -> LibraryError {
    LibraryError { code: Code::BadResult, message: format!("{function}() did not return {what}"), name: String::new(), stack: String::new() }
}

/// Bytes as a part: `{"$part": n}` in the arguments.
fn part(parts: &mut Vec<Vec<u8>>, bytes: &[u8]) -> Value {
    parts.push(bytes.to_vec());
    Value::object([("$part", Value::from(parts.len() - 1))])
}

impl Markdown {
    /// Loads the library at `path` (`Library::load`): the engine's thread.
    pub fn load(path: impl AsRef<std::path::Path>, options: &Value) -> Result<Markdown, zebkit::Error> {
        Ok(Markdown { library: Library::load(path, options)? })
    }

    /// The HTML of a Markdown document.
    pub async fn render(&self, text: &str, options: Option<Value>) -> Result<String, LibraryError> {
        let mut args = vec![Value::from(text)];
        if let Some(options) = options {
            args.push(options);
        }
        let reply = self.library.call_with("render", &Value::Array(args), &[], None).await?;
        reply.value.as_str().map(str::to_owned).ok_or_else(|| unexpected("render", "a string"))
    }

    /// The HTML of one line, without a paragraph around it.
    pub async fn render_inline(&self, text: &str) -> Result<String, LibraryError> {
        let args = vec![Value::from(text)];
        let reply = self.library.call_with("renderInline", &Value::Array(args), &[], None).await?;
        reply.value.as_str().map(str::to_owned).ok_or_else(|| unexpected("renderInline", "a string"))
    }

    /// Many documents in one call.
    pub async fn render_many(&self, texts: &[String]) -> Result<Vec<String>, LibraryError> {
        let args = vec![Value::Array(texts.iter().map(|item| Value::from(item.as_str())).collect())];
        let reply = self.library.call_with("renderMany", &Value::Array(args), &[], None).await?;
        reply.value.as_array().and_then(|items| items.iter().map(|item| item.as_str().map(str::to_owned)).collect::<Option<Vec<_>>>())
            .ok_or_else(|| unexpected("renderMany", "a list of strings"))
    }
}
